"""Writes plumb's Codex files from its Claude Code sources, so each rule and setting lives in one place.

Writes:
  plumb/.codex-plugin/plugin.json      from plumb/.claude-plugin/plugin.json
  .agents/plugins/marketplace.json     from .claude-plugin/marketplace.json
  plumb/codex/agents/<name>.toml       from plumb/agents/<name>.md (Codex custom agents)

Skills need no conversion: Codex reads the same SKILL.md files.

Usage: python3 scripts/build_codex.py [--check]
  --check  write nothing; fail if any generated file is missing or out of date (run in CI).
"""
import json
import os
import sys

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
PLUGIN = os.path.join(ROOT, "plumb")
MANIFEST_KEYS = ["name", "version", "description", "author", "license", "keywords"]


def read(path):
    with open(path) as f:
        return f.read()


def plugin_manifest():
    claude = json.loads(read(os.path.join(PLUGIN, ".claude-plugin", "plugin.json")))
    codex = {k: claude[k] for k in MANIFEST_KEYS if k in claude}
    codex["skills"] = "./skills/"
    return json.dumps(codex, indent=2) + "\n"


def marketplace():
    claude = json.loads(read(os.path.join(ROOT, ".claude-plugin", "marketplace.json")))
    plugins = [{
        "name": p["name"],
        "source": {"source": "local", "path": "./" + os.path.normpath(p["source"])},
        "policy": {"installation": "AVAILABLE", "authentication": "ON_USE"},
        "category": "Developer Tools",
    } for p in claude["plugins"]]
    codex = {"name": claude["name"], "interface": {"displayName": claude["name"]}, "plugins": plugins}
    return json.dumps(codex, indent=2) + "\n"


def frontmatter(text, path):
    """The name and description of a Claude Code agent file, and its body."""
    lines = text.split("\n")
    if lines[0] != "---" or "---" not in lines[1:]:
        sys.exit(f"{path}: no frontmatter")
    end = lines.index("---", 1)
    fields, key = {}, None
    for line in lines[1:end]:
        if line.startswith("  ") and key:
            fields[key] += line[2:] + "\n"
        elif ":" in line:
            key, value = line.split(":", 1)
            fields[key] = "" if value.strip() == "|" else value.strip()
        else:
            sys.exit(f"{path}: can't read frontmatter line {line!r}")
    for required in ("name", "description"):
        if not fields.get(required, "").strip():
            sys.exit(f"{path}: frontmatter has no {required}")
    return fields["name"], fields["description"].strip(), "\n".join(lines[end + 1:]).strip() + "\n"


def toml_text(value, path):
    # A TOML multi-line literal string keeps the text exactly as written, with no escaping.
    if "'''" in value:
        sys.exit(f"{path}: contains ''' which a TOML literal string can't hold")
    return "'''\n" + value + "'''"


def agents():
    out = {}
    folder = os.path.join(PLUGIN, "agents")
    for file in sorted(os.listdir(folder)):
        path = os.path.join(folder, file)
        name, description, body = frontmatter(read(path), path)
        out[os.path.join(PLUGIN, "codex", "agents", name + ".toml")] = (
            "# Generated by scripts/build_codex.py from plumb/agents/" + file + "; edit that file instead.\n"
            f"name = {json.dumps(name)}\n"
            f"description = {json.dumps(description)}\n"
            f"developer_instructions = {toml_text(body, path)}\n")
    return out


def main(check):
    files = {
        os.path.join(PLUGIN, ".codex-plugin", "plugin.json"): plugin_manifest(),
        os.path.join(ROOT, ".agents", "plugins", "marketplace.json"): marketplace(),
        **agents(),
    }
    stale = [p for p, text in files.items() if not os.path.exists(p) or read(p) != text]
    folder = os.path.join(PLUGIN, "codex", "agents")
    orphans = [os.path.join(folder, f) for f in sorted(os.listdir(folder))] if os.path.isdir(folder) else []
    orphans = [p for p in orphans if p not in files]
    if check:
        for p in stale + orphans:
            print(f"{os.path.relpath(p, ROOT)} is out of date: run python3 scripts/build_codex.py")
        sys.exit(1 if stale or orphans else 0)
    for p in orphans:
        os.remove(p)
        print(f"removed {os.path.relpath(p, ROOT)}")
    for p in stale:
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w") as f:
            f.write(files[p])
        print(f"wrote {os.path.relpath(p, ROOT)}")


if __name__ == "__main__":
    main("--check" in sys.argv[1:])
